    setTimeout(() => {
        // frappe.web_form.doc.name doesn't exist yet? 
        // Wait, the response is passed to handle_success(data).
        // Let's get the name from URL or we can fetch the last one if we must, 
        // BUT actually frappe.web_form.events.on('after_save') is better?
        // Wait, handle_success is called with response.message

        let tracking_no = "";

        // In v15, data is passed to render_success_page, but not stored in doc.name if new.
        // Wait, frappe.web_form.doc.name IS populated in standard frappe? 
        // Wait, the code says:
        // frappe.web_form.events.trigger("after_save");
        // But BEFORE that, it does NOT set frappe.web_form.doc.name ! 
        // Let's check how to get the name. We can intercept Ajax!

        // Actually, let's just make an Ajax call to get the latest Tramite for this session?
        // No, we can use jQuery ajaxComplete:
    }, 100);
};

// Better approach: listen to the fetch/ajax success globally, or use frappe.call hook
$(document).ajaxComplete(function(event, xhr, settings) {
    if (settings.url.indexOf('/api/method/frappe.website.doctype.web_form.web_form.accept') !== -1) {
        if (xhr.responseJSON && xhr.responseJSON.message && xhr.responseJSON.message.name) {
            let tracking_no = xhr.responseJSON.message.name;

            setTimeout(() => {
                $('.success-page').html(`
                    <div class="text-center" style="padding: 20px;">
                        <svg width="80" height="80" viewBox="0 0 16 16" class="text-success mb-3" fill="currentColor" xmlns="http://www.w3.org/2000/svg">
                          <path fill-rule="evenodd" d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0zm-3.97-3.03a.75.75 0 0 0-1.08.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-.01-1.05z"/>
                        </svg>
                        <h2>¡Trámite Validado!</h2>
                        <p>Su trámite ha sido registrado exitosamente. Guarde su número de seguimiento para futuras consultas.</p>
                        <div class="mt-4" style="font-size: 1.2rem; background-color: #f8f9fa; border: 2px dashed #007bff; border-radius: 8px; padding: 20px;">
                            <strong style="color: #007bff;">NÚMERO DE SEGUIMIENTO:</strong><br>
                            <span style="font-size: 2.2rem; font-family: monospace; letter-spacing: 2px; color: #343a40;">${tracking_no}</span>
                        </div>
                        <button class="btn btn-primary mt-4" onclick="window.print()" style="font-size: 1.1rem; padding: 10px 20px;">🖨️ Imprimir Comprobante</button>
                        <br>
                        <a class="btn btn-light mt-3" href="/ventanilla/new">Enviar otro trámite</a>
                    </div>
                `);
            }, 100);
        }
    }
});
